<template>
  <el-dialog
    :model-value="modelValue"
    width="80%"
    class="events-manage-dialog"
    @update:model-value="emit('update:modelValue', $event)"
  >
    <div class="manage-header">
      <el-input
        :model-value="searchKeyword"
        placeholder="搜索"
        clearable
        class="search-input"
        @update:model-value="emit('update:searchKeyword', $event)"
      >
        <template #prefix>
          <el-icon><Search /></el-icon>
        </template>
      </el-input>

      <div class="manage-actions">
        <el-tooltip content="添加" placement="top" effect="dark">
          <div class="action-button" @click="emit('open-add')">
            <el-icon :size="18"><Plus /></el-icon>
          </div>
        </el-tooltip>
        <el-tooltip content="编辑" placement="top" effect="dark">
          <div :class="['action-button', { active: isEditMode }]" @click="emit('toggle-edit')">
            <el-icon :size="18"><Edit /></el-icon>
          </div>
        </el-tooltip>
      </div>
    </div>

    <div class="manage-event-list">
      <el-tooltip
        v-for="event in filteredEvents"
        :key="event.id"
        placement="bottom"
        effect="dark"
      >
        <template #content>
          <div>{{ event.name }}</div>
        </template>
        <div
          :class="['manage-event-circle', { selected: selectedEventId === event.id }]"
          :style="{ backgroundColor: event.color }"
          @click="emit('event-click', event.id)"
        >
          <span class="manage-event-initial">{{ event.iconText || event.name.charAt(0) }}</span>
          <div v-if="isEditMode" class="manage-edit-badge">
            <el-icon :size="12"><Edit /></el-icon>
          </div>
          <span class="event-count-badge">
            {{ getEventCount(event.id) }}
          </span>
        </div>
      </el-tooltip>
      <div v-if="filteredEvents.length === 0" class="no-events-manage">
        {{ searchKeyword ? '未找到' : '暂无' }}
      </div>
    </div>

    <template #footer>
      <el-button @click="emit('update:modelValue', false)">关闭</el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { defineEmits, defineProps } from 'vue'
import { Edit, Plus, Search } from '@element-plus/icons-vue'

defineProps({
  modelValue: {
    type: Boolean,
    required: true
  },
  searchKeyword: {
    type: String,
    required: true
  },
  filteredEvents: {
    type: Array,
    required: true
  },
  isEditMode: {
    type: Boolean,
    required: true
  },
  selectedEventId: {
    type: String,
    default: null
  },
  getEventCount: {
    type: Function,
    required: true
  }
})

const emit = defineEmits([
  'update:modelValue',
  'update:searchKeyword',
  'open-add',
  'toggle-edit',
  'event-click'
])
</script>
