<template>
  <el-dialog
    :model-value="modelValue"
    width="500px"
    class="day-detail-dialog"
    @update:model-value="emit('update:modelValue', $event)"
  >
    <div class="day-detail-content">
      <div
        v-for="(eventInfo, index) in dayInfo.events"
        :key="eventInfo.id"
        class="event-detail-card"
        :style="{
          backgroundColor: eventInfo.color,
          marginBottom: index < dayInfo.events.length - 1 ? '12px' : '0'
        }"
      >
        <div class="event-card-header">
          <div class="event-card-icon">
            {{ eventInfo.iconText || eventInfo.name.charAt(0) }}
          </div>
          <div class="event-card-title">
            {{ eventInfo.name }}
          </div>
          <div class="event-card-count">
            <img src="../assets/t.png" class="event-card-count-icon" />
            <span>{{ getEventCount(eventInfo.id) }}</span>
          </div>
        </div>
        <div v-if="eventInfo.note" class="event-card-note">
          {{ eventInfo.note }}
        </div>
      </div>
      <div v-if="dayInfo.events.length === 0" class="no-events">
        暂无
      </div>
    </div>
    <template #footer>
      <el-button @click="emit('update:modelValue', false)">关闭</el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { defineEmits, defineProps } from 'vue'

defineProps({
  modelValue: {
    type: Boolean,
    required: true
  },
  dayInfo: {
    type: Object,
    required: true
  },
  getEventCount: {
    type: Function,
    required: true
  }
})

const emit = defineEmits(['update:modelValue'])
</script>
