<template>
  <div id="app">
    <div class="container">
      <EventSidebar
        :view-mode="viewMode"
        :is-edit-mode="isEditMode"
        :is-clear-mode="isClearMode"
        :events="events"
        :selected-event-id="selectedEventId"
        :get-event-count="getEventCount"
        @exit-month="exitMonth"
        @open-add="showAddDialog = true"
        @toggle-edit="toggleEditMode"
        @event-click="handleEventClick"
        @open-manage="showEventsManageDialog = true"
        @toggle-clear="toggleClearMode"
        @import-data="importData"
        @export-data="exportData"
      />

      <EventsManageDialog
        v-model="showEventsManageDialog"
        :search-keyword="searchKeyword"
        :filtered-events="filteredEvents"
        :is-edit-mode="isEditMode"
        :selected-event-id="selectedEventId"
        :get-event-count="getEventCount"
        @update:search-keyword="searchKeyword = $event"
        @open-add="showAddDialog = true"
        @toggle-edit="toggleEditMode"
        @event-click="handleManageEventClick"
      />

      <DayDetailDialog
        v-model="showDayDetailDialog"
        :day-info="selectedDayInfo"
        :get-event-count="getEventCount"
      />

      <EventFormDialog
        v-model="showAddDialog"
        title="添加"
        :form="newEventForm"
        :predefine-colors="predefineColors"
        @confirm="handleAddEventConfirm"
      />

      <EventFormDialog
        v-model="showEditDialog"
        title="编辑"
        :form="editEventForm"
        :predefine-colors="predefineColors"
        :is-edit="true"
        @confirm="handleEditEventConfirm"
        @delete="handleDeleteEventConfirm"
      />

      <div class="calendar-area">
        <GlobalStatsFloat
          :current-year="currentYear"
          :total-event-types="getTotalEventTypes()"
          :total-event-count="getTotalEventCount()"
          :year-event-count="getYearEventCount(currentYear)"
          @change-year="changeYear"
        />

        <YearCalendarView
          v-if="viewMode === 'year'"
          :current-year="currentYear"
          :get-month-days="getMonthDays"
          :has-color="hasColor"
          :get-day-style="getDayStyle"
          :get-month-event-types="getMonthEventTypes"
          :get-month-event-count="getMonthEventCount"
          @enter-month="enterMonth"
        />

        <MonthCalendarView
          v-else
          :current-year="currentYear"
          :current-month="currentMonth"
          :get-month-days="getMonthDays"
          :get-day-event-names="getDayEventNames"
          :has-color="hasColor"
          :get-day-style="getDayStyle"
          @toggle-day-event="toggleDayEvent"
        />
      </div>
    </div>
  </div>
</template>

<script setup>
import DayDetailDialog from './components/DayDetailDialog.vue'
import EventFormDialog from './components/EventFormDialog.vue'
import EventSidebar from './components/EventSidebar.vue'
import EventsManageDialog from './components/EventsManageDialog.vue'
import GlobalStatsFloat from './components/GlobalStatsFloat.vue'
import MonthCalendarView from './components/MonthCalendarView.vue'
import YearCalendarView from './components/YearCalendarView.vue'
import { useCalendarApp } from './composables/useCalendarApp'

const {
  currentYear,
  currentMonth,
  viewMode,
  selectedEventId,
  isEditMode,
  isClearMode,
  showAddDialog,
  showEditDialog,
  showDayDetailDialog,
  showEventsManageDialog,
  searchKeyword,
  filteredEvents,
  selectedDayInfo,
  newEventForm,
  editEventForm,
  events,
  // eventCounts,
  getEventCount,
  predefineColors,
  toggleEditMode,
  toggleClearMode,
  handleEventClick,
  handleManageEventClick,
  addEvent,
  saveEditEvent,
  confirmDeleteEvent,
  changeYear,
  enterMonth,
  exitMonth,
  getMonthDays,
  hasColor,
  getDayEventNames,
  getMonthEventTypes,
  getMonthEventCount,
  getTotalEventTypes,
  getTotalEventCount,
  getYearEventCount,
  getDayStyle,
  toggleDayEvent,
  exportData,
  importData
} = useCalendarApp()

const handleAddEventConfirm = (formData) => {
  newEventForm.value = { ...formData }
  addEvent(formData)
}

const handleEditEventConfirm = (formData) => {
  editEventForm.value = { ...formData }
  saveEditEvent(formData)
}

const handleDeleteEventConfirm = (formData) => {
  editEventForm.value = { ...formData }
  confirmDeleteEvent(formData)
}
</script>

<style src="./styles/app.css"></style>
