<template>
  <div class="month-view">
    <div class="large-calendar">
      <div class="month-watermark">
        {{ currentYear }}年 {{ currentMonth }}月
      </div>
      <div class="weekdays-large">
        <div v-for="day in weekdays" :key="day" class="weekday-large">
          {{ day }}
        </div>
      </div>
      <div class="days-large">
        <el-tooltip
          v-for="(day, index) in getMonthDays(currentMonth)"
          :key="index"
          :content="day ? getDayEventNames(currentYear, currentMonth, day) : ''"
          placement="top"
          effect="dark"
          :disabled="!day || !hasColor(currentYear, currentMonth, day)"
        >
          <div
            :class="[
              'day-cell-large',
              {
                empty: !day,
                clickable: day,
                colored: day && hasColor(currentYear, currentMonth, day),
                today: day && isToday(currentYear, currentMonth, day)
              }
            ]"
            :style="day ? getDayStyle(currentYear, currentMonth, day) : {}"
            @click="day && emit('toggle-day-event', currentYear, currentMonth, day)"
          >
            <span class="day-number">{{ day || '' }}</span>
            <span v-if="day && isToday(currentYear, currentMonth, day)" class="today-mark">今日</span>
          </div>
        </el-tooltip>
      </div>
    </div>
  </div>
</template>

<script setup>
import { defineEmits, defineProps } from 'vue'

const weekdays = ['日', '一', '二', '三', '四', '五', '六']

defineProps({
  currentYear: {
    type: Number,
    required: true
  },
  currentMonth: {
    type: Number,
    required: true
  },
  getMonthDays: {
    type: Function,
    required: true
  },
  getDayEventNames: {
    type: Function,
    required: true
  },
  hasColor: {
    type: Function,
    required: true
  },
  getDayStyle: {
    type: Function,
    required: true
  }
})

const emit = defineEmits(['toggle-day-event'])

const today = new Date()
const todayYear = today.getFullYear()
const todayMonth = today.getMonth() + 1
const todayDate = today.getDate()

function isToday(year, month, day) {
  return year === todayYear && month === todayMonth && day === todayDate
}
</script>

<style scoped>
.day-cell-large {
  position: relative;
  box-sizing: border-box;
  overflow: hidden;
}

.day-cell-large.today {
  border: 4px solid #584a32;
}

.today-mark {
  position: absolute;
  right: -8px;
  bottom: -10px;
  color: #584a32;
  font-size: 58px;
  line-height: 1;
  font-family: '宋体';
}
</style>
