<template>
  <el-dialog
    :model-value="modelValue"
    :title="title"
    width="400px"
    @update:model-value="emit('update:modelValue', $event)"
  >
    <el-form :model="form" label-width="80px">
      <el-form-item label="名称">
        <el-input
          v-model="form.name"
          placeholder="请输入名称"
        />
      </el-form-item>
      <el-form-item label="图标">
        <el-input
          v-model="form.iconText"
          maxlength="1"
        />
      </el-form-item>
      <el-form-item label="颜色">
        <el-color-picker
          v-model="form.color"
          :predefine="predefineColors"
        />
      </el-form-item>
      <el-form-item label="备注">
        <el-input
          v-model="form.note"
          type="textarea"
          :rows="10"
          placeholder="请输入备注"
          maxlength="2000"
          show-word-limit
        />
      </el-form-item>
    </el-form>
    <template #footer>
      <el-button @click="emit('update:modelValue', false)">取消</el-button>
      <el-button v-if="isEdit" type="danger" @click="emit('delete', { ...localForm })">删除</el-button>
      <el-button type="primary" @click="emit('confirm', { ...localForm })">{{ isEdit ? '保存' : '确定' }}</el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { computed, defineEmits, defineProps, ref, watch } from 'vue'

const props = defineProps({
  modelValue: {
    type: Boolean,
    required: true
  },
  title: {
    type: String,
    required: true
  },
  form: {
    type: Object,
    required: true
  },
  predefineColors: {
    type: Array,
    required: true
  },
  isEdit: {
    type: Boolean,
    default: false
  }
})

const emit = defineEmits(['update:modelValue', 'confirm', 'delete'])

const localForm = ref({
  id: '',
  name: '',
  iconText: '',
  color: '#8f7955',
  note: ''
})

watch(
  () => [props.modelValue, props.form],
  () => {
    localForm.value = {
      id: props.form.id || '',
      name: props.form.name || '',
      iconText: props.form.iconText || '',
      color: props.form.color || '#8f7955',
      note: props.form.note || ''
    }
  },
  { immediate: true, deep: true }
)

const form = computed(() => localForm.value)
</script>
